select.where:

             and received_seq = #{receivedSeq}
             and scene_type = #{sceneType}
             and unique_id = #{uniqueId}
             and person_name like concat(concat('%', #{personName}), '%')
             and dept_name like concat(concat('%', #{deptName}), '%')
             and channel_code = #{channelCode}
             and sub_treasury_code = #{subTreasuryCode}
             and sub_treasury_name like concat(concat('%', #{subTreasuryName}), '%')
             and scene_image = #{sceneImage}
             and stock_image = #{stockImage}
             and scene_stock_score = #{sceneStockScore}
             and result = #{result}
             and time_used = #{timeUsed}
             and server_id = #{serverId}
             and vendor_code = #{vendorCode}
             and algs_version = #{algsVersion}
             and batch_date = #{batchDate}
             and tenant_id = #{tenantId}

				and received_time >= to_date(#{beginTime},'yyyy-MM-dd HH24:mi:ss')


				and received_time <= to_date(#{endTime},'yyyy-MM-dd HH24:mi:ss')


				AND (log.dept_id = #{deptId} OR log.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE FIND_IN_SET (#{deptId},ancestors) ))


			${params.dataScope}

mapper.select:

         INNER JOIN (
		  SELECT unique_id as unique_id_tmp, MAX(received_time) AS received_time_tmp
		  FROM person_iris_search_log
		   where tenant_id = #{tenantId}
		  GROUP BY unique_id
		) AS tmp
		ON log.unique_id = tmp.unique_id_tmp AND log.received_time = tmp.received_time_tmp

             and received_seq = #{receivedSeq}
             and scene_type = #{sceneType}
             and unique_id = #{uniqueId}
             and person_name like concat(concat('%', #{personName}), '%')
             and dept_name like concat(concat('%', #{deptName}), '%')
             and channel_code = #{channelCode}
             and sub_treasury_code = #{subTreasuryCode}
             and sub_treasury_name like concat(concat('%', #{subTreasuryName}), '%')
             and scene_image = #{sceneImage}
             and stock_image = #{stockImage}
             and scene_stock_score = #{sceneStockScore}
             and result = #{result}
             and time_used = #{timeUsed}
             and server_id = #{serverId}
             and vendor_code = #{vendorCode}
             and algs_version = #{algsVersion}
             and batch_date = #{batchDate}
             and tenant_id = #{tenantId}

				and received_time >= to_date(#{beginTime},'yyyy-MM-dd HH24:mi:ss')


				and received_time <= to_date(#{endTime},'yyyy-MM-dd HH24:mi:ss')


				AND (log.dept_id = #{deptId} OR log.dept_id IN ( SELECT t.dept_id FROM sys_dept t WHERE FIND_IN_SET (#{deptId},ancestors) ))


			${params.dataScope}
